// Role → stat spread (multipliers on the gate's rolled base HP).
const ROLE_PROFILE = {
  brute:    { hp: 1.00, atk: 0.20, def: 0.04, speed: 0.8 },
  assassin: { hp: 0.75, atk: 0.24, def: 0.03, speed: 1.4 },
  caster:   { hp: 0.70, atk: 0.22, def: 0.03, speed: 1.0 },
  tank:     { hp: 1.35, atk: 0.12, def: 0.10, speed: 0.6 },
  swarm:    { hp: 0.60, atk: 0.16, def: 0.02, speed: 1.6 },
};

// Every craft material introduced by this bestiary (for recipes + /find).
const SL_MATERIALS = (() => {
  const s = new Set();
  for (const list of Object.values(SL_MONSTERS)) for (const m of list) for (const d of m.drops) s.add(d);
  return [...s];
})();

const SL_BY_NAME = (() => {
  const o = {};
  for (const [rank, list] of Object.entries(SL_MONSTERS)) for (const m of list) o[m.name] = { ...m, rank };
  return o;
})();

function pickForStrength(rank, strengthPct = 100) {
  const list = SL_MONSTERS[rank] || SL_MONSTERS.E;
  // Strength gates which tiers can appear: 60% → tiers 1-2, 80% → 1-4, 100% → 1-5 (weighted up).
  const maxTier = strengthPct >= 95 ? 5 : strengthPct >= 85 ? 4 : strengthPct >= 70 ? 3 : 2;
  const pool = list.filter(m => m.tier <= maxTier);
  const weighted = pool.flatMap(m => Array(m.tier).fill(m));
  return weighted[Math.floor(Math.random() * weighted.length)] || list[0];
}

module.exports = { SL_MONSTERS, SL_MATERIALS, SL_BY_NAME, ROLE_PROFILE, pickForStrength };
